static NSString *UNumber(id n){return TFAITokenCountString(n);}
static NSString *UDate(id n,BOOL day){if(!n)return @"—";NSDateFormatter *f=[NSDateFormatter new];f.dateFormat=day?@"yyyy-MM-dd":@"MM-dd HH:mm";return [f stringFromDate:[NSDate dateWithTimeIntervalSince1970:[n doubleValue]]];}
static NSString *UMetrics(NSDictionary *t){return [NSString stringWithFormat:DXLoc(@"输入 %@   ·   输出 %@\n缓存读取 %@   ·   命中率 %@\n%@ 次请求 · %@ 次返回完整用量"),UNumber(t[@"input"]),UNumber(t[@"output"]),UNumber(t[@"cachedInput"]),t[@"cacheHitRate"]?[NSString stringWithFormat:@"%.1f%%",[t[@"cacheHitRate"] doubleValue]*100]:DXLoc(@"未报告"),t[@"requests"],t[@"complete"]];}
NSString *TFAIBalanceCaption(NSDictionary *r){NSMutableArray *parts=[NSMutableArray new];for(NSDictionary *v in r[@"amounts"])[parts addObject:[NSString stringWithFormat:@"%@ %@",v[@"value"],[v[@"currency"] length]?v[@"currency"]:DXLoc(@"（单位未报告）")]];if(!parts.count)return [r[@"unsupported"] boolValue]?@"余额：不支持查询":r[@"error"]?@"余额：查询失败":DXLoc(@"余额：正在查询…");return [NSString stringWithFormat:@"%@：%@%@",[r[@"kind"] isEqual:@"credit_limit"]?@"Key 额度":DXLoc(@"余额"),[parts componentsJoinedByString:@" · "],[r[@"stale"] boolValue]?@"（上次结果）":@""];}
@interface TFUsageDetailPage : UITableViewController
@property NSArray *records;
