@end
@implementation TFUsageDetailPage
- (void)viewDidLoad{[super viewDidLoad];self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=120;}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 2;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?1:self.records.count;}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return s==0?@"范围汇总":DXLoc(@"每次模型请求");}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return s==1?@"一次用户提问可能产生多轮模型请求。工具执行本身不按请求重复计数，携带工具结果的下一轮模型请求会独立记录。中断或失败时已返回的用量仍保留。":nil;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{if(i.section==0)return AICell(UNumber(self.totals[@"total"]),UMetrics(self.totals),@"chart.bar");NSDictionary *r=self.records[i.row],*c=r[@"counts"];NSString *status=@{@"completed":DXLoc(@"完成"),@"failed":DXLoc(@"失败"),@"stopped":DXLoc(@"停止"),@"interrupted":DXLoc(@"中断"),@"running":DXLoc(@"进行中")}[r[@"status"]]?:DXLoc(@"未知");return AICell([NSString stringWithFormat:@"%@ · %@",UDate(r[@"startedAt"],NO),status],[NSString stringWithFormat:DXLoc(@"%@ / %@\n输入 %@ · 输出 %@\n缓存读取 %@ · 缓存写入 %@\n思考 %@ · 总计 %@"),r[@"connection_name"]?:@"",r[@"connection_model"]?:@"",UNumber(c[@"input"]),UNumber(c[@"output"]),UNumber(c[@"cachedInput"]),UNumber(c[@"cacheWrite"]),UNumber(c[@"reasoning"]),UNumber(c[@"total"])],@"arrow.up.arrow.down");}
@end
@interface TFUsagePage : UITableViewController
