@implementation TFUsagePage
- (void)viewDidLoad{[super viewDidLoad];self.title=self.session?@"本会话用量":@"用量统计";self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=92;self.refreshControl=[UIRefreshControl new];[self.refreshControl addTarget:self action:@selector(reload) forControlEvents:UIControlEventValueChanged];self.navigationItem.rightBarButtonItem=AIBar(@"calendar",DXLoc(@"自定义日期"),self,@selector(customDates));
 UIView *header=[[UIView alloc]initWithFrame:CGRectMake(0,0,320,110)];self.rangeControl=[[UISegmentedControl alloc]initWithItems:@[@"今天",DXLoc(@"7 天"),DXLoc(@"30 天"),@"全部"]];self.rangeControl.selectedSegmentIndex=1;self.rangeIndex=1;self.groupControl=[[UISegmentedControl alloc]initWithItems:@[@"按日",DXLoc(@"按会话"),DXLoc(@"按模型"),DXLoc(@"按连接")]];self.groupControl.selectedSegmentIndex=0;
 for(UISegmentedControl *control in @[self.rangeControl,self.groupControl]){control.translatesAutoresizingMaskIntoConstraints=NO;[header addSubview:control];[control addTarget:self action:@selector(filterChanged:) forControlEvents:UIControlEventValueChanged];}
 [NSLayoutConstraint activateConstraints:@[[self.rangeControl.topAnchor constraintEqualToAnchor:header.topAnchor constant:12],[self.rangeControl.leadingAnchor constraintEqualToAnchor:header.leadingAnchor constant:20],[self.rangeControl.trailingAnchor constraintEqualToAnchor:header.trailingAnchor constant:-20],[self.rangeControl.heightAnchor constraintEqualToConstant:34],[self.groupControl.topAnchor constraintEqualToAnchor:self.rangeControl.bottomAnchor constant:12],[self.groupControl.leadingAnchor constraintEqualToAnchor:self.rangeControl.leadingAnchor],[self.groupControl.trailingAnchor constraintEqualToAnchor:self.rangeControl.trailingAnchor],[self.groupControl.heightAnchor constraintEqualToConstant:34]]];self.tableView.tableHeaderView=header;[self reload];}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];if(self.records)[self reload];}
- (void)reload{if(self.loading)return;self.loading=YES;__weak typeof(self) weak=self;[(self.store?:TFAIUsageStore.shared) read:^(NSArray *records,NSString *error){NSMutableDictionary *names=[NSMutableDictionary new];NSMutableSet *projects=[NSMutableSet new];for(NSDictionary *r in records)[projects addObject:r[@"project"]?:@"general"];for(NSString *project in projects)for(NSDictionary *s in [TFAISessions sessions:project])if([s[@"id"] isKindOfClass:NSString.class]&&[s[@"title"] isKindOfClass:NSString.class])names[[NSString stringWithFormat:@"%@/%@",project,s[@"id"]]]=s[@"title"];dispatch_async(dispatch_get_main_queue(),^{TFUsagePage *s=weak;if(!s)return;s.loading=NO;s.records=records;s.loadError=error;s.sessionNames=names;[s.refreshControl endRefreshing];[s applyFilters];});}];}
- (void)filterChanged:(UISegmentedControl *)sender{if(sender==self.rangeControl){self.rangeIndex=sender.selectedSegmentIndex;self.start=nil;self.end=nil;}else self.groupIndex=sender.selectedSegmentIndex;[self applyFilters];}
- (void)applyFilters{
 NSDate *now=NSDate.date,*start=self.start,*end=self.end;NSCalendar *calendar=NSCalendar.currentCalendar;if(!start&&self.rangeIndex<3){NSDate *today=[calendar startOfDayForDate:now];start=[calendar dateByAddingUnit:NSCalendarUnitDay value:self.rangeIndex==0?0:self.rangeIndex==1?-6:-29 toDate:today options:0];}if(!end)end=[now dateByAddingTimeInterval:1];
 NSMutableArray *filtered=[NSMutableArray new];NSMutableDictionary *buckets=[NSMutableDictionary new];for(NSDictionary *r in self.records){double time=[r[@"startedAt"] doubleValue];if((start&&time<start.timeIntervalSince1970)||time>=end.timeIntervalSince1970||(self.project&&![r[@"project"] isEqual:self.project])||(self.session&&![r[@"session"] isEqual:self.session]))continue;[filtered addObject:r];NSString *key=self.groupIndex==0?UDate(r[@"startedAt"],YES):self.groupIndex==1?[NSString stringWithFormat:@"%@/%@",r[@"project"],r[@"session"]]:self.groupIndex==2?(r[@"connection_model"]?:DXLoc(@"未记录模型")):(r[@"connection_id"]?:DXLoc(@"未记录连接"));if(!buckets[key])buckets[key]=[NSMutableArray new];[buckets[key] addObject:r];}
 self.filtered=filtered;self.totals=TFAIUsageTotals(filtered);NSMutableArray *groups=[NSMutableArray new];for(NSString *key in buckets){NSArray *rows=buckets[key];NSDictionary *latest=rows.firstObject;NSString *title=self.groupIndex==1?(self.sessionNames[key]?:[NSString stringWithFormat:DXLoc(@"会话 %@"),[latest[@"session"] substringToIndex:MIN(8,[latest[@"session"] length])]]):self.groupIndex==3?(latest[@"connection_name"]?:@"连接"):key;[groups addObject:@{@"key":key,@"title":title,@"records":rows,@"time":latest[@"startedAt"],@"totals":TFAIUsageTotals(rows)}];}
 [groups sortUsingComparator:^NSComparisonResult(NSDictionary *a,NSDictionary *b){return [b[@"time"] compare:a[@"time"]];}];self.groups=groups;[self.tableView reloadData];
}
- (NSInteger)numberOfSectionsInTableView:(UITableView *)t{return 3;}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return s==0?1:s==1?3:MAX(1,self.groups.count);}
- (NSString *)tableView:(UITableView *)t titleForHeaderInSection:(NSInteger)s{return s==0?(self.start?[NSString stringWithFormat:@"%@ — %@",UDate(@(self.start.timeIntervalSince1970),YES),UDate(@([self.end dateByAddingTimeInterval:-1].timeIntervalSince1970),YES)]:DXLoc(@"所选时间范围")):s==1?@"缓存与统计口径":@[@"每日记录",@"会话",DXLoc(@"模型"),@"连接"][self.groupIndex];}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{if(s==0)return self.loadError?:[NSString stringWithFormat:DXLoc(@"本地记录 %@ 次请求 · %@ 个会话。下拉刷新。"),self.totals[@"requests"]?:@0,self.totals[@"sessions"]?:@0];if(s==1)return DXLoc(@"只统计升级后由 Dylix AI 会话（含 Remote / FLEX）发出的模型请求，不含能力测试。未返回 usage 的请求不估算计费。K = 1,000 tokens，M = 1,000,000 tokens，B = 1,000,000,000 tokens；缩写仅用于显示，记录保留精确数值。缓存是服务商报告的 token 数，并非手机磁盘大小，也无法据此得知服务端缓存容量。");return nil;}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{
 NSDictionary *v=self.totals?:@{};if(i.section==0){UITableViewCell *c=AICell(UNumber(v[@"total"]),[NSString stringWithFormat:DXLoc(@"累计 tokens\n%@"),UMetrics(v)],@"chart.bar.xaxis");c.textLabel.font=[UIFont monospacedDigitSystemFontOfSize:32 weight:UIFontWeightSemibold];c.selectionStyle=UITableViewCellSelectionStyleNone;return c;}
 if(i.section==1){NSArray *titles=@[@"缓存读取 / 写入",DXLoc(@"缓存命中率"),DXLoc(@"思考 tokens")];NSString *detail=i.row==0?[NSString stringWithFormat:DXLoc(@"读取 %@ · 写入 %@ tokens"),UNumber(v[@"cachedInput"]),UNumber(v[@"cacheWrite"])]:i.row==1?[NSString stringWithFormat:DXLoc(@"%@ · %@ / %@ 次请求报告缓存指标"),v[@"cacheHitRate"]?[NSString stringWithFormat:@"%.1f%%",[v[@"cacheHitRate"] doubleValue]*100]:DXLoc(@"未报告"),v[@"cacheKnown"]?:@0,v[@"requests"]?:@0]:[NSString stringWithFormat:DXLoc(@"%@ · 已包含在输出中，不重复相加"),UNumber(v[@"reasoning"])];UITableViewCell *c=AICell(titles[i.row],detail,@[@"externaldrive",@"bolt.horizontal",@"sparkles"][i.row]);c.selectionStyle=UITableViewCellSelectionStyleNone;return c;}
 if(!self.groups.count)return AICell(self.loading?@"正在读取…":DXLoc(@"此范围暂无用量"),DXLoc(@"发送消息后，实际 usage 会自动记录。"),@"tray");NSDictionary *group=self.groups[i.row];UITableViewCell *c=AICell(group[@"title"],UMetrics(group[@"totals"]),self.groupIndex==1?@"bubble.left.and.bubble.right":self.groupIndex==2?@"cpu":@"chart.bar");c.accessoryType=UITableViewCellAccessoryDisclosureIndicator;return c;
}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(i.section!=2||!self.groups.count)return;NSDictionary *g=self.groups[i.row];TFUsageDetailPage *page=[[TFUsageDetailPage alloc]initWithStyle:UITableViewStyleInsetGrouped];page.title=g[@"title"];page.records=g[@"records"];page.totals=g[@"totals"];[self.navigationController pushViewController:page animated:YES];}
- (void)customDates{UIViewController *page=[UIViewController new];page.title=DXLoc(@"日期范围");page.view.backgroundColor=UIColor.systemGroupedBackgroundColor;UIDatePicker *a=[UIDatePicker new],*b=[UIDatePicker new];for(UIDatePicker *p in @[a,b]){p.datePickerMode=UIDatePickerModeDate;p.preferredDatePickerStyle=UIDatePickerStyleCompact;p.maximumDate=NSDate.date;}
 a.date=self.start?:[NSCalendar.currentCalendar dateByAddingUnit:NSCalendarUnitDay value:-6 toDate:NSDate.date options:0];b.date=self.end?[self.end dateByAddingTimeInterval:-1]:NSDate.date;UILabel *la=[UILabel new],*lb=[UILabel new];la.text=DXLoc(@"开始日期");lb.text=DXLoc(@"结束日期（包含当天）");UIButton *save=[UIButton buttonWithType:UIButtonTypeSystem];[save setTitle:DXLoc(@"应用日期范围") forState:UIControlStateNormal];[save addAction:[UIAction actionWithHandler:^(__kindof UIAction *action){NSDate *start=[NSCalendar.currentCalendar startOfDayForDate:a.date],*end=[NSCalendar.currentCalendar dateByAddingUnit:NSCalendarUnitDay value:1 toDate:[NSCalendar.currentCalendar startOfDayForDate:b.date] options:0];if([start compare:end]!=NSOrderedAscending){AIAlert(page,DXLoc(@"日期范围无效"),DXLoc(@"结束日期不能早于开始日期。"));return;}self.start=start;self.end=end;self.rangeIndex=4;self.rangeControl.selectedSegmentIndex=UISegmentedControlNoSegment;[self applyFilters];[page dismissViewControllerAnimated:YES completion:nil];}] forControlEvents:UIControlEventTouchUpInside];UIStackView *stack=[[UIStackView alloc]initWithArrangedSubviews:@[la,a,lb,b,save]];stack.axis=UILayoutConstraintAxisVertical;stack.spacing=18;stack.translatesAutoresizingMaskIntoConstraints=NO;[page.view addSubview:stack];[NSLayoutConstraint activateConstraints:@[[stack.topAnchor constraintEqualToAnchor:page.view.safeAreaLayoutGuide.topAnchor constant:24],[stack.leadingAnchor constraintEqualToAnchor:page.view.leadingAnchor constant:24],[stack.trailingAnchor constraintEqualToAnchor:page.view.trailingAnchor constant:-24]]];UINavigationController *nav=[[UINavigationController alloc]initWithRootViewController:page];[self presentViewController:nav animated:YES completion:nil];}
@end
@interface TFBalancePage : UITableViewController
@property NSDictionary *connection;
@property NSArray *connections;
@property NSMutableDictionary *results;
@property NSMutableSet *loading;
@property TFAIProviderBalance *balanceService;
@end
@implementation TFBalancePage
- (void)viewDidLoad{[super viewDidLoad];self.title=DXLoc(@"余额与额度");self.results=[NSMutableDictionary new];self.loading=[NSMutableSet new];self.tableView.rowHeight=UITableViewAutomaticDimension;self.tableView.estimatedRowHeight=100;self.refreshControl=[UIRefreshControl new];[self.refreshControl addTarget:self action:@selector(refresh) forControlEvents:UIControlEventValueChanged];self.navigationItem.rightBarButtonItem=AIBar(@"arrow.clockwise",DXLoc(@"刷新余额"),self,@selector(refresh));}
- (void)viewWillAppear:(BOOL)animated{[super viewWillAppear:animated];self.connections=self.connection?@[self.connection]:TFAIConnections.all;[self load:NO];}
- (void)refresh{[self load:YES];}
- (void)load:(BOOL)force{for(NSDictionary *c in self.connections){NSString *key=c[@"id"];if(!key.length||[self.loading containsObject:key])continue;[self.loading addObject:key];__weak typeof(self) weak=self;[(self.balanceService?:TFAIProviderBalance.shared) fetch:c refresh:force completion:^(NSDictionary *result){TFBalancePage *s=weak;if(!s)return;s.results[key]=result;[s.loading removeObject:key];if(!s.loading.count)[s.refreshControl endRefreshing];[s.tableView reloadData];}];}if(!self.connections.count)[self.refreshControl endRefreshing];[self.tableView reloadData];}
- (NSInteger)tableView:(UITableView *)t numberOfRowsInSection:(NSInteger)s{return MAX(1,self.connections.count);}
- (NSString *)tableView:(UITableView *)t titleForFooterInSection:(NSInteger)s{return DXLoc(@"DeepSeek、硅基流动（国内）、Kimi（国内）、OpenRouter 按官方接口查询。OpenRouter 优先显示 Key 剩余额度。其他兼容站点自动尝试同源 Sub2API 钱包，无需手动设置接口。点信息按钮查看实际接口与错误详情。不支持查询并不代表余额为 0。余额仅用于展示，不影响模型连接。");}
- (UITableViewCell *)tableView:(UITableView *)t cellForRowAtIndexPath:(NSIndexPath *)i{if(!self.connections.count)return AICell(DXLoc(@"尚无模型连接"),DXLoc(@"先添加服务商连接和 API 密钥"),@"creditcard");NSDictionary *c=self.connections[i.row],*r=self.results[c[@"id"]];NSMutableArray *lines=[NSMutableArray new];for(NSDictionary *v in r[@"amounts"])[lines addObject:[NSString stringWithFormat:@"%@ %@",v[@"value"], [v[@"currency"] length]?v[@"currency"]:DXLoc(@"（单位未报告）")]];NSString *kind=[r[@"kind"] isEqual:@"credit_limit"]?@"Key 剩余额度":DXLoc(@"账户余额");NSString *value=lines.count?[lines componentsJoinedByString:@" · "]:[r[@"unsupported"] boolValue]?@"不支持查询":DXLoc(@"暂未获取");NSMutableString *detail=[NSMutableString stringWithFormat:@"%@：%@",kind,value];if(r[@"updatedAt"])[detail appendFormat:DXLoc(@"\n%@更新%@"),UDate(r[@"updatedAt"],NO),[r[@"stale"] boolValue]?@" · 上次结果，已过期":@""];if(r[@"error"])[detail appendFormat:@"\n%@",r[@"error"]];if([self.loading containsObject:c[@"id"]])[detail appendString:DXLoc(@"\n正在查询…")];UITableViewCell *cell=AICell(c[@"name"]?:DXLoc(@"服务商"),detail,@"creditcard");if([self.loading containsObject:c[@"id"]]){UIActivityIndicatorView *spin=[[UIActivityIndicatorView alloc]initWithActivityIndicatorStyle:UIActivityIndicatorViewStyleMedium];[spin startAnimating];cell.accessoryView=spin;}else if(r[@"endpoint"]){cell.accessoryType=UITableViewCellAccessoryDetailButton;}return cell;}
- (void)tableView:(UITableView *)t accessoryButtonTappedForRowWithIndexPath:(NSIndexPath *)i {
 if(i.row>=self.connections.count)return;NSDictionary *r=self.results[self.connections[i.row][@"id"]];
 NSMutableString *detail=[NSMutableString stringWithFormat:DXLoc(@"查询方式：%@\nGET %@\nHTTP：%@"),r[@"source"]?:DXLoc(@"自动识别"),r[@"endpoint"]?:DXLoc(@"未请求"),r[@"httpStatus"]?:DXLoc(@"未报告")];
 if(r[@"apiCode"])[detail appendFormat:DXLoc(@"\nAPI 错误码：%@"),r[@"apiCode"]];if(r[@"networkCode"])[detail appendFormat:DXLoc(@"\n网络错误码：%@"),r[@"networkCode"]];if(r[@"error"])[detail appendFormat:@"\n\n%@",r[@"error"]];
 [detail appendString:DXLoc(@"\n\n模型列表、聊天和余额使用不同接口；余额失败不会切换或禁用模型。诊断不包含密钥或响应正文。具有余额权限的密钥仍需由服务商确认。")] ;
 UIAlertController *alert=[UIAlertController alertControllerWithTitle:DXLoc(@"余额查询详情") message:detail preferredStyle:UIAlertControllerStyleAlert];[alert addAction:[UIAlertAction actionWithTitle:DXLoc(@"复制详情") style:UIAlertActionStyleDefault handler:^(UIAlertAction *action){UIPasteboard.generalPasteboard.string=detail;}]];[alert addAction:[UIAlertAction actionWithTitle:DXLoc(@"关闭") style:UIAlertActionStyleCancel handler:nil]];[self presentViewController:alert animated:YES completion:nil];
}
- (void)tableView:(UITableView *)t didSelectRowAtIndexPath:(NSIndexPath *)i{[t deselectRowAtIndexPath:i animated:YES];if(!self.connections.count)return;NSDictionary *c=self.connections[i.row];if([self.loading containsObject:c[@"id"]])return;[self.loading addObject:c[@"id"]];__weak typeof(self) weak=self;[(self.balanceService?:TFAIProviderBalance.shared) fetch:c refresh:YES completion:^(NSDictionary *r){weak.results[c[@"id"]]=r;[weak.loading removeObject:c[@"id"]];[weak.tableView reloadData];}];[t reloadData];}
@end
UIViewController *TFAIUsageController(NSString *project,NSString *session){TFUsagePage *v=[[TFUsagePage alloc]initWithStyle:UITableViewStyleInsetGrouped];v.project=project;v.session=session;return v;}
UIViewController *TFAIBalanceController(NSDictionary *connection){TFBalancePage *v=[[TFBalancePage alloc]initWithStyle:UITableViewStyleInsetGrouped];v.connection=connection;return v;}
